const API='https://fgomaujsdblpzxhnnqrg.supabase.co/rest/v1/';
const KEY='sb_publishable_JOUqLZDnfGu_yCa6k6FVDQ_AYwpr72i';
const PREFIX='gant02_20261024_';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY=86400000, date=s=>new Date(s+'T12:00:00Z'), iso=d=>d.toISOString().slice(0,10), add=(s,n)=>iso(new Date(+date(s)+n*DAY)), diff=(a,b)=>Math.round((date(a)-date(b))/DAY);
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const label={assigned:'Assigned',in_progress:'In progress',done:'Done'};
let projects=[],tasks=[],collapsed=new Set(),start=add(localToday(),-7),days=120,cw=36,pending=0,loading=false,loaded=false,editor=null,editorBaseline='',creating='project',draggingId=null,pointer=null,suppressClick=false;
const status=(s,failed=false)=>{$('sync').textContent=s;$('sync').classList.toggle('failed',failed);};
function error(e){$('error').textContent=e.message||String(e);$('error').hidden=false;status('Could not sync',true);}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,2600);}
async function api(table,method='GET',body=null,query=''){
 const response=await fetch(API+PREFIX+table+query,{method,headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=representation'},...(body?{body:JSON.stringify(body)}:{})});
 if(!response.ok){const e=await response.json().catch(()=>({message:response.statusText}));throw Error(e.message||'Database request failed');}return response.status===204?[]:response.json();
}
async function load(quiet=false){if(loading||pending||pointer)return;loading=true;if(!quiet)status('Syncing…');try{const [p,t]=await Promise.all([api('projects','GET',null,'?select=*&order=position,created_at'),api('tasks','GET',null,'?select=*&order=position,created_at')]);projects=p;tasks=t;loaded=true;render();status('All changes saved');$('error').hidden=true;}catch(e){error(e);}finally{loading=false;}}
async function mutate(table,method,body,id){pending++;status('Saving…');try{const result=await api(table,method,body,id?'?id=eq.'+encodeURIComponent(id):'');$('error').hidden=true;return result;}catch(e){error(e);throw e;}finally{pending--;if(!pending&&$('error').hidden)status('All changes saved');}}
async function updateTask(id,patch){const task=tasks.find(t=>t.id===id);if(!task)return;const old={...task};Object.assign(task,patch);render();try{const [saved]=await mutate('tasks','PATCH',patch,id);if(!saved)throw Error('Task was removed. Refresh to continue.');Object.assign(task,saved);render();}catch(e){Object.assign(task,old);render();error(e);}}
function visible(t){return (!$('status-filter').value||t.status===$('status-filter').value)&&(!q()||[t.name,t.assignee,projects.find(p=>p.id===t.project_id)?.name].join(' ').toLowerCase().includes(q()));}
function q(){return $('search').value.trim().toLowerCase();}
function options(selected){return projects.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');}
function bands(){let h='';for(let i=0;i<days;i++){const d=add(start,i);if([0,6].includes(date(d).getUTCDay()))h+=`<span class="weekend-band" style="left:${i*cw}px;width:${cw}px"></span>`;}const today=diff(localToday(),start);if(today>=0&&today<days)h+=`<span class="today-line" style="left:${today*cw+cw/2}px"></span>`;return h;}
function spanHTML(s,e,project=false,t=null){if(!s||!e)return '';const x=diff(s,start),n=diff(e,s)+1;if(x+n<=0||x>=days)return '';const left=Math.max(0,x)*cw+2,width=(Math.min(days,x+n)-Math.max(0,x))*cw-4;if(project)return `<span class="project-span" style="left:${left}px;width:${width}px"></span>`;return `<div class="bar ${t.status}" data-id="${t.id}" role="button" tabindex="0" aria-label="${esc(t.name)}, ${s} to ${e}, ${label[t.status]}. Arrow keys move one day; Shift and arrow keys resize." title="${esc(t.name)} · ${s} → ${e}" style="left:${left}px;width:${width}px"><span class="resize left" data-edge="start"></span><span class="bar-label">${esc(t.name)}</span><span class="resize right" data-edge="end"></span></div>`;}
function render(){
 const filter=$('project-filter').value;$('project-filter').innerHTML='<option value="">All projects</option>'+options(filter);$('new-task').disabled=!projects.length||!loaded;$('new-project').disabled=!loaded;
 const dayHeaders=[],months=[];for(let i=0;i<days;i++){const d=add(start,i),dt=date(d),key=d.slice(0,7);if(!months.length||months.at(-1).key!==key)months.push({key,text:dt.toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'}),n:0});months.at(-1).n++;dayHeaders.push(`<div class="day ${[0,6].includes(dt.getUTCDay())?'weekend':''} ${d===localToday()?'today':''}" title="${d}"><small>${dt.toLocaleDateString('en-US',{weekday:'narrow',timeZone:'UTC'})}</small>${dt.getUTCDate()}</div>`);}
 const width=days*cw,band=bands();let h=`<div class="grid-header"><div class="frozen"><div class="col-head">#</div><div class="col-head">Task / project</div><div class="col-head">Status</div><div class="col-head">Assignee</div><div class="col-head">Start</div><div class="col-head">Finish</div></div><div class="calendar" style="width:${width}px"><div class="months">${months.map(m=>`<div class="month" style="width:${m.n*cw}px">${m.text}</div>`).join('')}</div><div class="days">${dayHeaders.join('')}</div></div></div>`;
 let count=0;for(const p of projects.filter(p=>!filter||p.id===filter)){
 const all=tasks.filter(t=>t.project_id===p.id),rows=all.filter(visible);if((q()||$('status-filter').value)&&!rows.length)continue;const dates=all.filter(t=>t.start_date),s=dates.length?dates.map(t=>t.start_date).sort()[0]:null,e=dates.length?dates.map(t=>t.end_date).sort().at(-1):null;
 h+=`<div class="row project-row" data-project="${p.id}"><div class="frozen"><button class="collapse" data-collapse="${p.id}" aria-label="${collapsed.has(p.id)?'Expand':'Collapse'} project">${collapsed.has(p.id)?'▸':'▾'}</button><button class="project-name" data-open-project="${p.id}">${esc(p.name)}</button><span class="project-count">${all.length} tasks · ${all.filter(t=>t.status==='done').length} done</span><button class="project-add" data-add="${p.id}">＋ Task</button></div><div class="timeline" style="width:${width}px">${spanHTML(s,e,true)}</div></div>`;
 if(collapsed.has(p.id))continue;
 for(const t of rows){count++;h+=`<div class="row task-row" data-task="${t.id}" data-project="${p.id}"><div class="frozen"><div class="cell grip" draggable="true" data-drag="${t.id}" title="Drag to reorder or move between projects">⠿</div><div class="cell name-cell"><button data-open="${t.id}" title="Open task details">${esc(t.name)}</button>${t.notes?'<span class="note-mark" title="Has notes">≡</span>':''}</div><div class="cell"><select aria-label="Status for ${esc(t.name)}" data-field="status" data-id="${t.id}" class="status-select ${t.status}">${Object.entries(label).map(([v,l])=>`<option value="${v}" ${v===t.status?'selected':''}>${l}</option>`).join('')}</select></div><div class="cell"><input aria-label="Assignee for ${esc(t.name)}" data-field="assignee" data-id="${t.id}" value="${esc(t.assignee)}" placeholder="—"></div><div class="cell"><input aria-label="Start date for ${esc(t.name)}" type="date" data-field="start_date" data-id="${t.id}" value="${t.start_date||''}"></div><div class="cell"><input aria-label="Finish date for ${esc(t.name)}" type="date" data-field="end_date" data-id="${t.id}" value="${t.end_date||''}"></div></div><div class="timeline task-timeline" data-id="${t.id}" style="width:${width}px">${band}${spanHTML(t.start_date,t.end_date,false,t)}</div></div>`;}
 h+=`<div class="row add-row"><div class="frozen"><button data-add="${p.id}">＋ Add a task</button></div><div class="timeline" style="width:${width}px"></div></div>`;
 }
 if(!projects.length)h+=`<div class="empty"><h2>Make room for your next project.</h2><p>Create a project, add a few tasks, then drag across the calendar to give each one a start and finish. Everything saves as you go.</p><button class="primary" id="empty-project">＋ Create your first project</button></div>`;
 else if(!count&&(q()||$('status-filter').value))h+='<div class="empty"><h2>No matching tasks</h2><p>Try another search or clear your filters.</p></div>';
 $('grid').innerHTML=h;$('summary').textContent=`${projects.length} project${projects.length===1?'':'s'} · ${tasks.length} tasks · ${tasks.filter(t=>t.status==='done').length} completed`;$('task-count').textContent=`${count} visible tasks`;$('range-label').textContent=date(start).toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});document.documentElement.style.setProperty('--day',cw+'px');
}
function create(type,project){creating=type;$('create-title').textContent=type==='project'?'New project':'New task';$('create-submit').textContent=type==='project'?'Create project':'Create task';$('create-project-label').hidden=type==='project';$('create-project').innerHTML=options(project||$('project-filter').value);$('create-name').value='';$('create-dialog').showModal();$('create-name').focus();}
$('new-project').onclick=()=>create('project');$('new-task').onclick=()=>create('task');$('cancel-create').onclick=$('cancel-create-bottom').onclick=()=>$('create-dialog').close();
$('create-form').onsubmit=async e=>{e.preventDefault();const name=$('create-name').value.trim();if(!name)return;const table=creating==='project'?'projects':'tasks',items=creating==='project'?projects:tasks;const payload={name,position:Math.max(0,...items.map(x=>x.position))+1024};if(creating==='task')payload.project_id=$('create-project').value;$('create-submit').disabled=true;try{const [item]=await mutate(table,'POST',payload);items.push(item);collapsed.delete(payload.project_id);$('create-dialog').close();render();toast(creating==='project'?'Project created':'Task created — drag on its calendar row to schedule');}catch{}finally{$('create-submit').disabled=false;}};
for(const id of ['project-filter','status-filter','search'])$(id).addEventListener(id==='search'?'input':'change',render);
$('refresh').onclick=()=>load();$('zoom').onchange=()=>{cw=Number($('zoom').value);render();};$('prev').onclick=()=>{start=add(start,-28);render();};$('next').onclick=()=>{start=add(start,28);render();};$('today').onclick=()=>{start=add(localToday(),-7);$('grid-wrap').scrollLeft=0;render();};
$('grid').addEventListener('click',e=>{if(suppressClick)return;const a=e.target.closest('button');if(a?.dataset.open)openEditor('tasks',a.dataset.open);else if(a?.dataset.openProject)openEditor('projects',a.dataset.openProject);else if(a?.dataset.add)create('task',a.dataset.add);else if(a?.dataset.collapse){const id=a.dataset.collapse;collapsed.has(id)?collapsed.delete(id):collapsed.add(id);render();}else if(a?.id==='empty-project')create('project');});
$('grid').addEventListener('change',e=>{const {field,id}=e.target.dataset;if(!field)return;const t=tasks.find(x=>x.id===id),patch={[field]:e.target.value};if(field.endsWith('_date')){const d=e.target.value;if(!d)patch.start_date=patch.end_date=null;else if(field==='start_date'){patch.end_date=!t.end_date||d>t.end_date?d:t.end_date;}else patch.start_date=!t.start_date||d<t.start_date?d:t.start_date;}updateTask(id,patch);});
function cellAt(ev,el){return Math.max(0,Math.min(days-1,Math.floor((ev.clientX-el.getBoundingClientRect().left)/cw)));}
$('grid').addEventListener('pointerdown',e=>{if(e.button!==0||pending)return;const line=e.target.closest('.task-timeline');if(!line)return;const t=tasks.find(x=>x.id===line.dataset.id),bar=e.target.closest('.bar'),edge=e.target.dataset.edge;pointer={id:t.id,line,bar,mode:bar?(edge||'move'):'draw',x:e.clientX,y:e.clientY,index:cellAt(e,line),oldStart:t.start_date,oldEnd:t.end_date,moved:false};line.setPointerCapture(e.pointerId);e.preventDefault();});
$('grid').addEventListener('pointermove',e=>{if(!pointer)return;const p=pointer,delta=Math.round((e.clientX-p.x)/cw);if(Math.abs(e.clientX-p.x)>3||Math.abs(e.clientY-p.y)>3)p.moved=true;let s=p.oldStart,f=p.oldEnd;if(p.mode==='draw'){const i=cellAt(e,p.line);s=add(start,Math.min(p.index,i));f=add(start,Math.max(p.index,i));}else if(p.mode==='move'){s=add(p.oldStart,delta);f=add(p.oldEnd,delta);}else if(p.mode==='start'){s=add(p.oldStart,delta);if(s>f)s=f;}else{f=add(p.oldEnd,delta);if(f<s)f=s;}p.newStart=s;p.newEnd=f;let selection=p.line.querySelector('.selection');if(!selection){selection=document.createElement('div');selection.className='selection';p.line.append(selection);}selection.style.left=Math.max(0,diff(s,start))*cw+'px';selection.style.width=(Math.min(days,diff(f,start)+1)-Math.max(0,diff(s,start)))*cw+'px';selection.title=`${s} → ${f}`;});
async function finishPointer(e){if(!pointer)return;const p=pointer;pointer=null;p.line.querySelector('.selection')?.remove();if(p.line.hasPointerCapture(e.pointerId))p.line.releasePointerCapture(e.pointerId);suppressClick=true;setTimeout(()=>suppressClick=false,100);if(p.mode!=='draw'&&!p.moved){openEditor('tasks',p.id);return;}const s=p.newStart||(p.mode==='draw'?add(start,p.index):p.oldStart),f=p.newEnd||s;if(s!==p.oldStart||f!==p.oldEnd)await updateTask(p.id,{start_date:s,end_date:f});}
$('grid').addEventListener('pointerup',finishPointer);$('grid').addEventListener('pointercancel',()=>{pointer?.line.querySelector('.selection')?.remove();pointer=null;});
$('grid').addEventListener('keydown',e=>{const bar=e.target.closest('.bar');if(!bar)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();openEditor('tasks',bar.dataset.id);}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const t=tasks.find(t=>t.id===bar.dataset.id),n=e.key==='ArrowRight'?1:-1,patch=e.shiftKey?{end_date:add(t.end_date,n)}:{start_date:add(t.start_date,n),end_date:add(t.end_date,n)};if(!e.shiftKey||patch.end_date>=t.start_date)updateTask(t.id,patch);}});
$('grid').addEventListener('dragstart',e=>{const handle=e.target.closest('[data-drag]');if(!handle)return;draggingId=handle.dataset.drag;e.dataTransfer.setData('text/plain',draggingId);e.dataTransfer.effectAllowed='move';handle.closest('.row').classList.add('dragging');});
$('grid').addEventListener('dragover',e=>{const row=e.target.closest('[data-project]');if(!draggingId||!row)return;e.preventDefault();document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));row.classList.add('drop-target');});
$('grid').addEventListener('drop',e=>{const row=e.target.closest('[data-project]');if(!row||!draggingId)return;e.preventDefault();const id=draggingId,project_id=row.dataset.project,siblings=tasks.filter(t=>t.project_id===project_id&&t.id!==id),target=siblings.findIndex(t=>t.id===row.dataset.task);let position;if(target<0)position=Math.max(0,...siblings.map(t=>t.position))+1024;else position=(siblings[target].position+(siblings[target-1]?.position??siblings[target].position-2048))/2;collapsed.delete(project_id);draggingId=null;updateTask(id,{project_id,position}).then(()=>{tasks.sort((a,b)=>a.position-b.position);render();});});
$('grid').addEventListener('dragend',()=>{draggingId=null;document.querySelectorAll('.drop-target,.dragging').forEach(x=>x.classList.remove('drop-target','dragging'));});
function sanitize(html){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set(['P','DIV','BR','B','STRONG','I','EM','U','S','UL','OL','LI','BLOCKQUOTE','H2','H3','A']);for(const el of [...doc.body.querySelectorAll('*')]){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','IMG'].includes(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}const href=el.getAttribute('href');for(const a of [...el.attributes])el.removeAttribute(a.name);if(el.tagName==='A'&&href&&/^https?:\/\//i.test(href)){el.setAttribute('href',href);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}}return doc.body.innerHTML;}
function editorState(){return JSON.stringify([$ ('detail-name').value,$('detail-project').value,$('detail-status').value,$('detail-assignee').value,$('detail-start').value,$('detail-end').value,$('notes').innerHTML]);}
function openEditor(table,id){if(editor&&!closeEditor())return;const item=(table==='tasks'?tasks:projects).find(x=>x.id===id);if(!item)return;editor={table,id};$('detail-type').textContent=table==='tasks'?'TASK DETAILS':'PROJECT DETAILS';$('detail-name').value=item.name;$('task-fields').hidden=table!=='tasks';$('detail-project').innerHTML=options(item.project_id);$('detail-status').value=item.status||'assigned';$('detail-assignee').value=item.assignee||'';$('detail-start').value=item.start_date||'';$('detail-end').value=item.end_date||'';$('notes').innerHTML=sanitize(item.notes||'');$('detail-message').textContent='';$('drawer').hidden=$('drawer-shade').hidden=false;editorBaseline=editorState();$('detail-name').focus();}
function closeEditor(force=false){if(!force&&editor&&editorState()!==editorBaseline&&!confirm('Discard unsaved changes?'))return false;editor=null;$('drawer').hidden=$('drawer-shade').hidden=true;return true;}
$('close-drawer').onclick=$('drawer-shade').onclick=()=>closeEditor();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&editor)closeEditor();});window.addEventListener('beforeunload',e=>{if(pending||(editor&&editorState()!==editorBaseline)){e.preventDefault();e.returnValue='';}});
$('clear-dates').onclick=()=>{$('detail-start').value=$('detail-end').value='';};
document.querySelectorAll('[data-command]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{$('notes').focus();document.execCommand(b.dataset.command,false);};});
$('add-link').onmousedown=e=>e.preventDefault();$('add-link').onclick=()=>{const url=prompt('Link URL (https://…)');if(!url)return;if(!/^https?:\/\//i.test(url)){toast('Use a full https:// or http:// URL');return;}$('notes').focus();document.execCommand('createLink',false,url);};
$('notes').addEventListener('paste',e=>{e.preventDefault();const html=e.clipboardData.getData('text/html'),plain=e.clipboardData.getData('text/plain');document.execCommand('insertHTML',false,html?sanitize(html):esc(plain).replace(/\n/g,'<br>'));});
$('detail-form').onsubmit=async e=>{e.preventDefault();if(!editor)return;const name=$('detail-name').value.trim();if(!name)return;const current={...editor},patch={name,notes:sanitize($('notes').innerHTML)};if(current.table==='tasks'){const s=$('detail-start').value,f=$('detail-end').value;if((s&&!f)||(!s&&f)||s>f){$('detail-message').textContent='Choose a valid start and finish.';return;}Object.assign(patch,{project_id:$('detail-project').value,status:$('detail-status').value,assignee:$('detail-assignee').value,start_date:s||null,end_date:f||null});}$('save-detail').disabled=true;try{const [saved]=await mutate(current.table,'PATCH',patch,current.id);if(!saved)throw Error('This item was removed. Refresh to continue.');const item=(current.table==='tasks'?tasks:projects).find(x=>x.id===current.id);Object.assign(item,saved);closeEditor(true);render();toast('Changes saved');}catch(e){$('detail-message').textContent=e.message;}finally{$('save-detail').disabled=false;}};
$('delete-item').onclick=async()=>{if(!editor)return;const current={...editor};if(!confirm(current.table==='projects'?'Delete this project and all of its tasks?':'Delete this task?'))return;$('delete-item').disabled=true;try{await mutate(current.table,'DELETE',null,current.id);if(current.table==='projects'){projects=projects.filter(x=>x.id!==current.id);tasks=tasks.filter(x=>x.project_id!==current.id);}else tasks=tasks.filter(x=>x.id!==current.id);closeEditor(true);render();toast('Deleted');}catch{}finally{$('delete-item').disabled=false;}};
